SESSION = "44d9667ede034913ba33421599357d6b"

def call_tool(name, args):
    payload = {"jsonrpc": "2.0", "id": 800, "method": "tools/call", "params": {"name": name, "arguments": args}}
    cmd = ["curl", "-s", "http://are-sidecar:8000/mcp",
           "-H", "Content-Type: application/json",
           "-H", "Accept: application/json, text/event-stream",
           "-H", f"mcp-session-id: {SESSION}",
           "-d", json.dumps(payload)]
    result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
    output = result.stdout
    for line in output.split('\n'):
        if line.startswith('data: '):
            d = json.loads(line[6:])
            if 'result' in d and d['result']:
                content = d['result'].get('content', [])
                if content:
                    return json.loads(content[0]['text'])
    return None

# Send cancellation email
content = "Hej \u00c5ke,\n\nSince I have not heard back from you regarding the Film Production Day scheduled for Saturday, October 19, I have cancelled the event. If you would like to reschedule at a later date, please let me know.\n\nBest regards,\nAstrid"

res = call_tool("Emails__send_email", {
    "recipients": ["ake.lindstrom@filmproduktion.se"],
    "subject": "Cancellation: Film Production Day",
    "content": content
})
print(f"Email send result: {res}")
EOF
